    "structure_table": [
      [
        "第一百碗麵"
      ],
      [
        "背景",
        "做【 資源回收 】的老人牽著小男孩，走進麵攤。"
      ],
      [
        "起因",
        "老人點了最便宜的【 陽春麵 】給孫子，自己只喝水。\n老闆看了說他們是【 第一百 】個客人，那碗麵他請客。"
      ],
      [
        "經過",
        "1.寒流來那天，小男孩想請阿公吃麵，在攤子旁數有多少      【 客人 】進去吃麵，人數一直停留在85人。\n2.老闆看見小男孩的舉動，【 打電話 】給老顧客和朋友，邀請他們來店裡吃麵。\n3.小男孩數到第【 99 】個客人時，把老人拉進店裡，完成請阿公吃麵的心願。\n4.老闆娘想送一碗麵給小男孩，老闆卻說小男孩正在學習     「【 不吃飯也會飽 】」的道理。"
      ],
      [
        "結果",
        "吃完麵後，祖孫倆【 滿足/幸福 】的離去。"
      ]
    ],
