    "story_id": 1030,
    "title": "工地大嫂",
    "genre": "說明文",
    "strategy_name": "從上下文推測詞義",
    "source_file": "G5-L3工地大嫂（從上下文推測詞義）.docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "定義",
        "作者稱六十歲以下，和丈夫一起來工地工作的女性叫大嫂。"
      ],
      [
        "來工地的原因",
        "1.工地環境【 粗野陽剛 】，女性多半與父親、丈夫或兄弟同行，以確保安全。\n2.大嫂往往早婚，年紀較【 輕 】，學歷相對【 不高/低 】。\n3.跟著丈夫進工地，不僅可多出一分勞力，也能\n　【 約束 】丈夫、照應工作。"
      ],
      [
        "大嫂的類型",
        "1.互補型：丈夫技術好，但是好強高傲。\n大嫂們【 長袖善舞 】，擅長【 接案 】調度，使工程銜接無虞。\n2.管束型：丈夫技術不錯，但個性較【 不穩定 】。大嫂們會默默收管丈夫，使其工作穩定順暢。\n3.人脈型：大嫂【 度量胸襟 】宏大、人脈廣闊，可隨時調度各方人手協助趕工。"
      ],
      [
        "大嫂在工地的功用",
        "1.【 調停 】工人爭執。\n2.提供偏方與【 藥物 】給身體不適的工人。\n3.協助【 埋葬 】工地死亡的貓狗。\n4.工程順利時，帶工人同樂慶祝。\n5.工程不順利時，下一步該怎麼做，大嫂會【 指點迷津 】。"
      ],
      [
        "總結",
        "工地大嫂是臺灣社會中堅強、溫柔又美麗的女性縮影，值得眾人【 尊敬 】。"
      ]
    ],
