    "title": "從〈螞蟻與蟋蟀〉看生命的多樣性",
    "genre": "說明文",
    "strategy_name": "用表格整理訊息-比較異同",
    "source_file": "G7-L4從〈螞蟻與蟋蟀〉看生命的多樣性（用表格整理訊息-比較異同）.docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "從〈螞蟻與蟋蟀〉看生命的多樣性"
      ],
      [
        "關於螞蟻",
        "1.螞蟻工作往往　 集體出動  　，展現有紀律、有秩序的行動。\n2.螞蟻是　　社會性　　昆蟲，分工嚴密。\n3.整個蟻群的核心是蟻后，所以螞蟻都有ㄧ個共同目標：　　　　　　　　　　　　\n　　　　協助蟻后繁衍後代　　　　。"
      ],
      [
        "關於蟋蟀",
        "1.會發出鳴叫聲的都是【 雄蟋蟀□雌蟋蟀 】。（單選）\n2.蟋蟀高歌是為了　　求偶　　，爭取繁衍的機會，或是　　警告　　其他雄蟋蟀不要靠近地盤。\n3.每一隻蟋蟀都【 可以□不可以 】自行繁衍後代。（單選）"
      ],
      [
        "兩者並列原因",
        "起源於   伊索寓言     ，諷刺蟋蟀鎮日高歌，不知貯糧的天兵。\n寓言中的螞蟻是　 勤奮 　的代表，蟋蟀被批評為　 懶惰 　。"
      ],
      [
        "生命多樣性",
        "1.蟋蟀的高歌與螞蟻的存糧一樣，都是生物遵從　本能　　的行動。\n2.螞蟻藉由　合作　，來達成　群體繁衍　　　的需求；\n　蟋蟀則透過　　競爭　　，延續自己的基因。"
      ],
      [
        "總結",
        "人們看待事物時，不要只從自己的角度出發，否則很容易得出\n　片面　　的結論。"
      ]
    ],
