    "genre": "記敘文",
    "strategy_name": "推論策略-推論人物的動機、情緒與想法",
    "source_file": "G8-L6戲院、賭場、檳榔攤：在時代夾縫中成長的我（推論策略-推論人物的動機、情緒與想法）.docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "戲院、賭場、檳榔攤：在時代夾縫中成長的我"
      ],
      [
        "家庭背景",
        "1.作者家在美濃定居開戲院。後來因為經營困難，家裡經濟陷入困頓。\n2.家中長輩為了要挽救局勢，做了哪些事？（請打勾，複選）\n　借錢　 賭博　在戲院旁搭鐵皮屋販賣東西\n3.作者從小在家幫忙，曾遇過有人強闖戲院、遭鹹豬手騷擾、打掃到吸食強力膠的垃圾。作者的家就是戲院，而戲院令人感到【 □安全不安 】。"
      ],
      [
        "突破困境",
        "1.師長暗中協助：導師送　【 參考書 】；理化老師提供宿舍【 自習 】。\n2.作者摸索出讀書的時機與訣竅：顧檳榔攤寫卷、戲院顧門，電影放映時背課本、深夜在微弱的燈光下【 解題 】\n3.結果：考上【 臺南女中 】、【 臺南師專 】，鎮上貼賀榜。最後當了老師、校長，還成了一位作家。"
      ],
      [
        "總結",
        "回顧作者的成長經歷，下列哪些敘述正確？（請打勾，複選）\n□她一直以來都很理解父母的辛苦，不曾抱怨過\n她曾經對家庭的動盪感到埋怨與難堪\n隨著年齡增長，她逐漸體會父母的無奈與辛勞\n她感謝老師在困境中給予支援與溫暖\n□她因為環境惡劣，選擇放棄努力而聽天由命\n她相信自己擁有改變命運的力量，並付諸行動"
      ]
    ],
