    "structure_table": [
      [
        "隱形的征服者"
      ],
      [
        "歷史事件與結局",
        "事件：1532年西班牙征服南美洲 印加帝國\n1.皮薩羅率領168名士兵對戰8萬士兵的印加帝國軍隊。\n2.面對印加帝國龐大的軍隊時，西班牙士兵的心理感受(請打勾，單選)\n感到畏懼，因為敵軍人數遠遠超過自己\n□感到興奮，因為他們深信自己一定會獲勝\n結局：印加帝國的崩潰\n1.原本強大的【 印加帝國 】在西班牙人到來後迅速瓦解。\n2.印加人放棄原本的【 信仰 】和語言，改信天主教，【 西班牙 】語成為南美洲的主要語言。"
      ],
      [
        "提問",
        "1.勢單力薄的西班牙人，在短時間內征服印加帝國，他們靠的是什麼？",
        "2.為什麼歐洲人攜帶這麼多致命的病菌，自己卻不會生病？"
      ],
      [
        "說明",
        "賈德•戴蒙的研究指出，是西班牙人從__帶過去的病菌。",
        "一千多年前，歐洲已爆發多次大瘟疫，現在歐洲人身上已有【 歐洲 】。【 抗體 】"
      ],
      [
        "說明",
        "病菌所造成的影響",
        "(配對連線) 帝國有什麼改變?"
      ],
      [
        "詳細說明",
        "1524年，歐洲人帶來的天花傳染給美洲原住民，導致大量死亡。",
        "● ● 大家紛紛改變信仰，更\n加速印加帝國的崩解。"
      ],
      [
        "詳細說明",
        "1528年印加皇帝因天花病逝，繼承人爭奪王位，引發長年內戰。",
        "● ● 印加帝國長年的內戰，導致帝國衰弱不堪。"
      ],
      [
        "詳細說明",
        "印加人發現信仰天主教的西班牙人沒有生病，認為西班牙人的神才是真神。",
        "● ● 爆發大規模疫情，導致\n8年內印加帝國人口減半。"
      ],
      [
        "總結",
        "1.如果沒有病菌，印加帝國可能仍保持強盛。\n2.天花等疾病成為西班牙人征服印加的重要推力，改變了美洲的歷史。"
      ]
    ],
