    "genre": "說明文",
    "strategy_name": "推論策略-找作者主要論點",
    "source_file": "G8-L10「按讚」背後的真相（推論策略-找作者主要論點）.docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "「按讚」背後的真相！"
      ],
      [
        "議題-現象",
        "很多人看到貼文會自然按「讚」，但這個動作背後，隱藏著你未必察覺的【 真相 】"
      ],
      [
        "原因",
        "按讚之所以讓人容易一直滑，是因為它帶來【 即時回饋感 】，讓人覺得被重視、被看見。"
      ],
      [
        "論點一/論據",
        "論點：按讚不只是數字，有些人把自己的【 自我價值 】建立在按讚數上，心情隨之起伏，甚至影響【 心理健康 】。\n論據：\n(1)澳洲網紅為追求按讚數，反覆拍照修圖，最後刪除帳號。\n(2)美國11歲瑟琳娜因按讚數太少而自卑焦慮"
      ],
      [
        "論點二/論據",
        "1.論點：平台會記下你的偏好，推播更多【 類似內容 】給你，久而久之形成【 過濾泡泡 】，讓你視野變窄。\n2.論據：\n(1)同學按了遊戲影片的讚，之後手機幾乎被遊戲內容佔滿。\n(2)莫莉看了情緒低落貼文後，平台大量推送負面內容，導致悲劇"
      ],
      [
        "結論與建議",
        "按讚本身沒有錯，但不要讓按讚數左右情緒與自我價值；可以使用【 隱藏按讚數 】功能減壓，也要留意滑動內容，學會【 平衡 】使用社群媒體。"
      ]
    ],
