    "title": "我能不能選擇告別方式?",
    "genre": "說明文",
    "strategy_name": "比較多元觀點",
    "source_file": "G8-L17我能不能選擇告別方式0225(比較多元觀點).docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "我能不能選擇告別方式"
      ],
      [
        "案例（段1）",
        "問題：傅達仁罹患胰臟癌，劇痛難耐，他想結束折磨，但在臺灣沒有合法管道。\n解決：他寫信給蔡總統盼【 推動立法 】，但爭議大、難有共識\n結果：在家人陪伴下前往瑞士，依當地制度以【 協助自殺 】方式離世。"
      ],
      [
        "核心議題（段2）",
        "當生命只剩疼痛，是否能【 選擇告別 】？誰能協助做決定？"
      ],
      [
        "「安樂死／協助自殺」類型(段3)",
        "「安樂死／協助自殺」分三種： \n1.【 撤除維生醫療 】：不做無效醫療，讓生命自然走到終點\n2.【 安樂死 】：他人主動用藥，讓無法自我決定的病人死亡\n3.【 協助自殺 】：在醫療人員的協助下，自己按下注射藥劑的開關，完成最後一步。"
      ],
      [
        "臺灣現況(段3)",
        "臺灣目前已有【 安寧緩和醫療 】與【 病人自主權利法 】，主要保障的是第一種；第二、三種仍不合法。"
      ],
      [
        "對議題看法：多元觀點(段4-6)",
        "1.贊成：在【 法律監督 】下開放讓病人可選擇結束生命。\n2.反對：擔心開放後【 適用範圍擴大 】；也擔心弱勢病患因【 費用／照護壓力 】而被迫選擇死亡。\n3.保留：主張先落實【 臨終照顧 】：疼痛控制、心理支持、長照與照顧者喘息更普及。"
      ],
      [
        "兩難(段7)",
        "1.難解的問題同時牽涉【 人權 】、信仰、【 風險 】與制度設計。\n2.若開放要設計【 審查、申訴與監督 】；若不開放要確保病人不被【 疼痛 】吞沒、補足【 照護缺口 】。"
      ]
    ],
