        "1.秦國服役早而重。\n2.服役是【 三弟/黑夫 】，沒有兵餉，連衣物都要自己準備。\n3.秦王統一大業，卻將戰爭成本【 難料 】到底層民眾身上。【 夏衣 】【 錢 】【 獎勵 】【 義務 】【 轉嫁 】"
