    "genre": "說明文",
    "strategy_name": "正向思考-培養心理韌性",
    "source_file": "G9-L14焚而不毀的倫敦（正向思考-培養心理韌性）.docx",
    "worksheet_docx_url": "",
    "structure_source": "docx-keypoints-2026-06-18",
    "structure_table": [
      [
        "焚而不毀的倫敦"
      ],
      [
        "英倫大轟炸(段1~3)",
        "1.1940年秋天，倫敦遭遇【 德國 】轟炸機空襲，持續了許多個月。\n2.轟炸後的倫敦【 滿目瘡痍 】、焦土遍野，街上滿是殘垣敗瓦。\n3.英國的死亡人數 眾多  □稀少。(請打勾，單選)"
      ],
      [
        "倫敦市民的反應(段5~9)",
        "1.轟炸期間，民眾都盡自己所能幫助受難的人員。\n2.警報解除後，大家開始恢復正常生活。\n3.民眾以幽默的態度面對這場災難，英國人用「克制的上唇」來形容這種面不改色的【 心理韌性 】。"
      ],
      [
        "心理學家的發現(段10)",
        "1.大轟炸後，幸運存活者非但沒有嚇壞，反而產生了強烈的自信與平靜，這現象被稱為【 倖存者的鎮定 】。\n2.心理學家將大爆炸後的倫敦人民分成三類，分析大轟炸對他們的影響。\n(1)哪幾類人產生了強烈的自信與平靜？(請打勾，複選)\n①直接受害者   ②間接受害者   □③未受波及者\n(2)哪一類人最為恐懼？(請打勾，單選)\n□①直接受害者   □②間接受害者   ③未受波及者\n(3)重災區的人們能「親身體驗」，能「參與救災」，因此獲得【 掌控感 】，就能讓自己找回秩序與平衡。"
      ],
      [
        "作者結論(段11~13)",
        "1.人類的恐懼，不是對危險本身的反應，而是對【 未知 】的想像。\n2.當人們真正【 面對 】恐懼，恐懼就沒那麼可怕\n3.當危險變成日常，人們反而會見怪不怪，【 處變不驚 】。\n4.大轟炸帶來的是一種名為【 心理靭性 】的力量。"
      ]
    ],
